    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [renamed, second]);
    await stop();
    await start();
    assert.deepEqual(await getTasks(), [restoredTask, nextTask]);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [renamed, second]);
